// Depends on the counter service. cordis only runs this plugin while 'counter' exists:
// disable or reload the counter plugin and this tile disappears, then comes back.
import { definePlugin } from 'tilr'

export default definePlugin({
  name: 'stats',
  author: 'dan',
  tags: ['demo'],
  version: __TILR_VERSION__,
  inject: ['ui', 'counter'],
  apply(ctx) {
    const body = ctx.ui.tile({ title: 'stats' })
    const line = document.createElement('div')
    const since = document.createElement('div')
    since.className = 'muted'
    since.textContent = `mounted ${new Date().toLocaleTimeString('en-GB')}`
    body.append(line, since)

    let clicks = 0
    const render = () => {
      line.innerHTML = `counter is <span class="accent"></span>, <b></b> clicks since mount`
      // The casts: the markup is the line above.
      ;(line.querySelector('span') as HTMLElement).textContent = String(ctx.counter.value)
      ;(line.querySelector('b') as HTMLElement).textContent = String(clicks)
    }
    // The listener is removed with the plugin.
    ctx.on('counter/change', () => {
      clicks++
      render()
    })
    render()
  },
})
